        raise ValueError('label required')
    if not isinstance(data.get('confidence'), (int, float)):
        raise ValueError('confidence required')
    return {'label': data['label'], 'confidence': float(data['confidence'])}

"""Проверяемый путь: 1.20.8 AI для учёбы / RAG answer."""
def build_rag_answer_8(question, chunks):
    if not chunks:
        return {'answer': 'Не нашёл данных в базе знаний.', 'sources': [], 'no_answer': True}
    answer = ' '.join(chunk['text'] for chunk in chunks)
    return {'answer': answer, 'sources': [chunk['source'] for chunk in chunks], 'no_answer': False}

