    return state.get('node') == 'finish' or state.get('attempts', 0) >= 5

"""Проверяемый путь: 5.12.4 Безопасный вайбкодинг / Diff review."""
def review_diff_safely_4(diff):
    risks = []
    if '+eval(' in diff:
        risks.append('dangerous eval')
    if 'API_KEY=' in diff:
        risks.append('secret')
    return {'safe': not risks, 'review': risks}

"""Проверяемый путь: 5.12.5 Безопасный вайбкодинг / Secret scan."""
def scan_secret_diff_5(diff):
    tokens = ['API_KEY=', 'SECRET_KEY=', 'TOKEN=']
    found = [token for token in tokens if token in diff]
    return {'safe': not found, 'review': found}

"""Проверяемый путь: 5.12.6 Безопасный вайбкодинг / Dependency risk."""
def review_dependency_risk_6(package, approved):
    if package not in approved:
        return {'safe': False, 'review': 'unknown dependency'}
    return {'safe': True, 'review': 'approved'}

"""Проверяемый путь: 5.12.7 Безопасный вайбкодинг / Hallucinated API."""
def detect_hallucinated_api_7(call_name, allowed_calls):
    return {'safe': call_name in allowed_calls, 'review': None if call_name in allowed_calls else 'unknown api'}

"""Проверяемый путь: 5.12.8 Безопасный вайбкодинг / Test gate."""
def require_test_gate_8(diff, check_result):
    has_code = any(line.startswith('+') and line.endswith('.py') for line in diff.splitlines())
    if has_code and check_result != 'passed':
        return {'safe': False, 'review': 'missing tests gate'}
    return {'safe': True, 'review': 'tests passed'}
